-------------------------------------------------------------------------------
-- File       : tb_OpenBlaze8_rom.vhd
-- Author     : mrosiere
-------------------------------------------------------------------------------
-- Description: ROM bank of tb_OpenBlaze8 : one ROM per test program
--              (entity ROM_<name> generated by pbcc_gen), output of the ROM
--              sel_i (index of the name in C_TESTS of tb_OpenBlaze8_tests_pkg,
--              0 : no program, instruction 0)
-------------------------------------------------------------------------------
-- Copyright (c) 2026
-------------------------------------------------------------------------------
-- Revisions  :
-- Date        Version  Author   Description
-- 2026-11-20  1.0      mrosiere Created (split of tb_OpenBlaze8)
-------------------------------------------------------------------------------

library ieee;
use     ieee.std_logic_1164.all;

entity tb_OpenBlaze8_rom is
  port (
    clk_i         : in  std_logic
   ;sel_i         : in  natural
   ;address_i     : in  std_logic_vector(10-1 downto 0)
   ;instruction_o : out std_logic_vector(18-1 downto 0)
  );
end entity tb_OpenBlaze8_rom;

architecture sim of tb_OpenBlaze8_rom is

  type     rom_data_t is array (natural range <>) of std_logic_vector(18-1 downto 0);
  signal   rom_data   : rom_data_t(0 to 49) := (others => (others => '0'));

begin  -- architecture sim

  instruction_o <= rom_data(sel_i) when sel_i <= rom_data'high else
                   (others => '0');

  -- test_000_default : default program (writes the OK trigger)
  ins_test_000_default : entity work.ROM_test_000_default(rtl)
    port map
    (clk_i         => clk_i
    ,cke_i         => '1'
    ,address_i     => address_i
    ,instruction_o => rom_data(1)
    );

  -- test_001_test_ok : OK trigger only
  ins_test_001_test_ok : entity work.ROM_test_001_test_ok(rtl)
